  if (t.isFunctionDeclaration(path.node)) {
    return path.node.body;
  }
  if (t.isVariableDeclarator(path.node)) {
    const init = path.node.init;
    if (t.isArrowFunctionExpression(init) || t.isFunctionExpression(init)) {
      return init.body;
    }
  }
  return null;
}

