pub fn get_hook_body(node: &Decl) -> Option<&BlockStmt> {
    // Check if it's a function declaration
    if let Decl::Fn(fn_decl) = node {
        return fn_decl.function.body.as_ref();
    }

    // Check if it's a variable declarator with arrow/function expression
    if let Decl::Var(var_decl) = node {
        for decl in &var_decl.decls {
            if let Some(init) = &decl.init {
                match init.as_ref() {
                    Expr::Arrow(arrow) => {
                        if let BlockStmtOrExpr::BlockStmt(body) = &*arrow.body {
                            return Some(body);
                        }
                    }
                    Expr::Fn(fn_expr) => {
                        return fn_expr.function.body.as_ref();
                    }
                    _ => {}
                }
            }
        }
    }

    None
}
